var info=new System.Collections.Generic.List<object>();
foreach(var sc in UnityEngine.SceneManagement.SceneManager.GetAllScenes()) info.Add(new {path=sc.path,dirty=sc.isDirty,loaded=sc.isLoaded});
var p=UnityEditor.AssetDatabase.LoadAssetAtPath<UnityEngine.GameObject>("Assets/Prefabs/Character.prefab");
foreach(var c in p.GetComponentsInChildren<UnityEngine.Collider2D>(true))UnityEngine.Debug.Log(c.name+" enabled="+c.enabled+" rb="+(c.attachedRigidbody==null?"null":c.attachedRigidbody.name+" "+c.attachedRigidbody.constraints));
UnityEngine.Debug.Log(Codely.Newtonsoft.Json.JsonConvert.SerializeObject(info));
var scene=UnityEditor.SceneManagement.EditorSceneManager.OpenScene("Assets/Scenes/Level04_Town.unity",UnityEditor.SceneManagement.OpenSceneMode.Additive);
try{
 var map=scene.GetRootGameObjects().SelectMany(r=>r.GetComponentsInChildren<UnityEngine.Tilemaps.Tilemap>(true)).First(t=>t.GetComponent<UnityEngine.Tilemaps.TilemapCollider2D>()!=null);
 var cells=new System.Collections.Generic.List<object>();foreach(var pos in map.cellBounds.allPositionsWithin)if(map.HasTile(pos)){var wp=map.GetCellCenterWorld(pos);if((wp.y>27&&wp.y<33)||(wp.y>36&&wp.y<40))cells.Add(new{cell=new[]{pos.x,pos.y,pos.z},world=new[]{wp.x,wp.y},tile=UnityEditor.AssetDatabase.GetAssetPath(map.GetTile(pos))});}
 System.IO.File.WriteAllText("scripts/clearance-20261112/fourth-cells.json",Codely.Newtonsoft.Json.JsonConvert.SerializeObject(cells));
 UnityEngine.Debug.Log("map="+map.name+" scale="+map.transform.lossyScale+" cell="+map.layoutGrid.cellSize);
}finally{UnityEditor.SceneManagement.EditorSceneManager.CloseScene(scene,true);}
